((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
globalThis.KENGURU_GRADES_7_8 = [{"year":2018,"id":"2018-7-8","grades":[7,8],"label":"7–8 классы","tasksUrl":"assets/kenguru/kenguru_2018_class_7-8.pdf","answersUrl":"assets/kenguru/kenguru_2018_answers.pdf","solutionUrl":null,"answerLetters":"АБВГД","cards":[{"number":1,"title":"Бусинка на проволоке","question":"Бусинку на рисунке продвинули от начала проволоки до ее конца. Что мы увидим?","options":[{"image":"assets/grades-7-8/2018/task-01-answer-1.svg","description":"Кенгуру стоит, голова справа вверху"},{"image":"assets/grades-7-8/2018/task-01-answer-2.svg","description":"Голова слева вверху, хвост справа внизу"},{"image":"assets/grades-7-8/2018/task-01-answer-3.svg","description":"Голова справа внизу, задние лапы слева"},{"image":"assets/grades-7-8/2018/task-01-answer-4.svg","description":"Голова справа внизу, задние лапы вверху"},{"image":"assets/grades-7-8/2018/task-01-answer-5.svg","description":"Голова слева внизу, задние лапы вверху"}],"condition":{"src":"assets/grades-7-8/2018/task-01.svg","width":240,"height":146,"alt":"Проволока с тремя дугами. На левом вертикальном конце бусинка с кенгуру, у правого вертикального конца — пунктирное место для бусинки."},"answer":4,"points":3,"review":[{"title":"Решение","text":"Бусинка поворачивается вместе с направлением проволоки. На первой дуге направление меняется на 180°, на нижней дуге поворот на 180° идёт в обратную сторону, а на третьей — снова в сторону первого поворота."},{"title":"Ответ","text":"Первые два поворота взаимно компенсируются. В конце рисунок повёрнут на 180° относительно начального. Голова кенгуру окажется внизу слева, как в варианте Д."}]},{"number":2,"title":"Ближе к двум","question":"Сколько целых положительных чисел ближе к 2, чем к 7?","options":[{"text":"1"},{"text":"2"},{"text":"3"},{"text":"4"},{"text":"5"}],"condition":null,"answer":3,"points":3,"review":[{"title":"Решение","text":"Середина между 2 и 7 находится в точке (2 + 7) ÷ 2 = 4,5. Все числа левее середины ближе к 2."},{"title":"Ответ","text":"Из положительных целых подходят 1, 2, 3 и 4. Таких чисел четыре."}]},{"number":3,"title":"Цепочка из колец","question":"Несколько из нарисованных колец образуют цепочку, в которую входит кольцо А. Сколько колец в этой цепочке?","options":[{"text":"4"},{"text":"5"},{"text":"6"},{"text":"7"},{"text":"8"}],"condition":{"src":"assets/grades-7-8/2018/task-03.svg","width":198,"height":162,"alt":"Восемь колец, пересекающихся попарно. У большого верхнего кольца стоит буква А. На пересечениях видно, какая дуга проходит сверху."},"answer":1,"points":3,"review":[{"title":"Решение","text":"Два кольца сцеплены, когда в одном месте пересечения одно кольцо проходит поверх другого, а во втором пересечении — под ним. Если и там и там оно сверху, кольца можно разнять."},{"title":"Решение","text":"От кольца А цепочка идёт в одну сторону к маленькому верхнему кольцу. В другую сторону она идёт через кольцо слева от центра, маленькое кольцо под ним и нижнее кольцо."},{"title":"Ответ","text":"Кольцо А и эти четыре соседних звена вместе дают пять колец."}]},{"number":4,"title":"Килодюжина месяцев","question":"Сколько веков в одной килодюжине месяцев?","options":[{"text":"1"},{"text":"6"},{"text":"10"},{"text":"12"},{"text":"100"}],"condition":null,"answer":2,"points":3,"review":[{"title":"Решение","text":"Килодюжина — это тысяча дюжин. Дюжина месяцев составляет один год, так что килодюжина месяцев — 1000 лет."},{"title":"Ответ","text":"В одном веке 100 лет. В 1000 годах 10 веков."}]},{"number":5,"title":"Две вписанные окружности","question":"В прямоугольник 7 × 11 вписаны две одинаковые окружности (см. рисунок). Чему равно расстояние между их центрами?","options":[{"text":"2"},{"text":"3"},{"text":"4"},{"text":"5"},{"text":"6"}],"condition":{"src":"assets/grades-7-8/2018/task-05.svg","width":150,"height":108,"alt":"Прямоугольник 7 × 11 с двумя пересекающимися окружностями. Обе касаются верхней и нижней сторон, каждая — своей боковой стороны."},"answer":2,"points":3,"review":[{"title":"Решение","text":"Обе окружности касаются верхней и нижней сторон прямоугольника. Их диаметр равен 7, а радиус — 3,5."},{"title":"Решение","text":"Расстояние от центра левой окружности до левой стороны равно 3,5, и столько же от центра правой до правой стороны."},{"title":"Ответ","text":"Между центрами остаётся 11 − 3,5 − 3,5 = 4."}]},{"number":6,"title":"Самая длинная запись","question":"Жан-Кристоф продолжает изучать русский язык. Из всех двузначных чисел он выбрал такое, для словесной записи которого нужно наибольшее количество букв. Сколько букв в записи этого числа?","options":[{"text":"13"},{"text":"14"},{"text":"15"},{"text":"16"},{"text":"17"}],"condition":null,"answer":4,"points":3,"review":[{"title":"Решение","text":"Числа от 10 до 19 записываются одним словом длиной не более 12 букв. Среди названий остальных десятков самое длинное — «восемьдесят», 11 букв."},{"title":"Ответ","text":"Самые длинные названия единиц — «четыре», «восемь» и «девять», по 6 букв. Например, «восемьдесят четыре» содержит 11 + 6 = 17 букв, и больше получить невозможно."}]},{"number":7,"title":"Сумма под квадратом","question":"Известно, что (2² + 2² + … + 2²)² = 4⁴. Сколько слагаемых в скобке?","options":[{"text":"4"},{"text":"5"},{"text":"6"},{"text":"7"},{"text":"8"}],"condition":null,"answer":0,"points":3,"review":[{"title":"Решение","text":"Сумма в скобке положительна. Если её квадрат равен 4⁴, сама сумма равна 4² = 16."},{"title":"Ответ","text":"Каждое слагаемое равно 2² = 4. Поэтому слагаемых 16 ÷ 4 = 4."}]},{"number":8,"title":"Дата из двух цифр","question":"Будем записывать любую дату, используя восемь цифр. Например, сегодня 15.03.2018. Миша нашел ближайшую дату в будущем, в записи которой используется только две разные цифры. В каком месяце находится эта дата?","options":[{"text":"январь"},{"text":"февраль"},{"text":"март"},{"text":"ноябрь"},{"text":"декабрь"}],"condition":null,"answer":1,"points":3,"review":[{"title":"Решение","text":"В самих записях 2018 и 2019 годов больше двух разных цифр. Первый возможный год — 2020. В дне и месяце тогда разрешены только цифры 0 и 2."},{"title":"Ответ","text":"Первый месяц с такими цифрами — 02, а первый допустимый день — 02. Получается 02.02.2020, то есть февраль."}]},{"number":9,"title":"Девять прямоугольников","question":"Большой прямоугольник составлен из девяти одинаковых прямоугольников, в каждом из которых бóльшая сторона равна 10. Чему равен периметр большого прямоугольника?","options":[{"text":"40"},{"text":"48"},{"text":"76"},{"text":"81"},{"text":"90"}],"condition":{"src":"assets/grades-7-8/2018/task-09.svg","width":118,"height":106,"alt":"Большой прямоугольник. Сверху и снизу по два горизонтальных прямоугольника, посередине пять вертикальных."},"answer":2,"points":3,"review":[{"title":"Решение","text":"Сверху лежат два прямоугольника длинной стороной вдоль края, поэтому ширина всей фигуры равна 2 × 10 = 20."},{"title":"Решение","text":"В среднем ряду по этой ширине стоят пять коротких сторон. Каждая равна 20 ÷ 5 = 4. Высота всей фигуры равна 4 + 10 + 4 = 18."},{"title":"Ответ","text":"Периметр большого прямоугольника равен 2 × (20 + 18) = 76."}]},{"number":10,"title":"Цифры не меньше пяти","question":"Наименьшее трехзначное число, в котором цифр, не меньших 5, не меньше, чем цифр, меньших 5, равно","options":[{"text":"105"},{"text":"115"},{"text":"151"},{"text":"155"},{"text":"555"}],"condition":null,"answer":3,"points":3,"review":[{"title":"Решение","text":"Из трёх цифр не меньше двух должны быть хотя бы 5. Чтобы число было наименьшим, первую цифру берём равной 1."},{"title":"Ответ","text":"Тогда обе оставшиеся цифры должны быть не меньше 5. Берём наименьшие возможные, то есть 5 и 5. Получаем 155."}]},{"number":11,"title":"Одиннадцать точек","question":"На прямой расположено 11 точек. Сумма расстояний от первой точки слева до остальных десяти равна 2018, а сумма расстояний от второй точки слева до остальных десяти равна 2000. Чему равно расстояние между первой и второй точками?","options":[{"text":"1"},{"text":"2"},{"text":"3"},{"text":"9"},{"text":"18"}],"condition":null,"answer":1,"points":4,"review":[{"title":"Решение","text":"Обозначим расстояние между первыми двумя точками через d. Оно входит в обе суммы. Все девять остальных точек лежат правее второй."},{"title":"Решение","text":"Расстояние от первой до каждой из этих девяти точек на d больше, чем от второй. Разность сумм равна 9d = 2018 − 2000 = 18."},{"title":"Ответ","text":"Значит, d = 2."}]},{"number":12,"title":"Угол в треугольнике","question":"Внутри равнобедренного треугольника ABC с основанием BC отмечена точка D так, что AD = DC. Известно, что ∠BAD = α, ∠DCB = 4α и ∠DAC = 3α. Найдите α.","options":[{"text":"10°"},{"text":"12°"},{"text":"14°"},{"text":"15°"},{"text":"18°"}],"condition":{"src":"assets/grades-7-8/2018/task-12.svg","width":172,"height":180,"alt":"Равнобедренный треугольник ABC с точкой D внутри. Отмечены углы BAD = α, DAC = 3α и DCB = 4α и одинаковая длина сторон AB и AC."},"answer":0,"points":4,"review":[{"title":"Решение","text":"Угол BAC равен α + 3α = 4α. В равнобедренном треугольнике ABC угол ACB равен 90° − 2α."},{"title":"Решение","text":"Угол ACD равен ACB минус DCB, то есть 90° − 6α. При этом в равнобедренном треугольнике ADC углы ACD и DAC равны."},{"title":"Ответ","text":"Поэтому 90° − 6α = 3α. Решение этого уравнения даёт α = 10°."}]},{"number":13,"title":"Солнечные дни Сильвера","question":"На Карибских островах 350 дней в году — солнечные. Пират Сильвер прибыл на один из островов 1 января 2018 года. Какое наименьшее количество дней ему придется оставаться на острове, чтобы среди этих дней обязательно было два солнечных дня подряд?","options":[{"text":"21"},{"text":"30"},{"text":"31"},{"text":"32"},{"text":"35"}],"condition":null,"answer":3,"points":4,"review":[{"title":"Решение","text":"В 2018 году 365 дней, поэтому несолнечных дней всего 15. Без соседних солнечных дней между каждыми двумя солнечными должен быть несолнечный."},{"title":"Решение","text":"Можно начать год с чередования солнечных и несолнечных дней. Так 15 несолнечных дней разделят 16 солнечных, и первые 31 день ещё могут пройти без двух солнечных подряд."},{"title":"Ответ","text":"За 32 дня при 15 несолнечных днях уже будет хотя бы 17 солнечных. Разделить их 15 несолнечными невозможно, поэтому 32 дней достаточно."}]},{"number":14,"title":"Развертка коробки","question":"На рисунке изображена развертка бумажной коробки и указаны некоторые длины. Чему равен объем этой коробки?","options":[{"text":"43"},{"text":"70"},{"text":"80"},{"text":"100"},{"text":"1820"}],"condition":{"src":"assets/grades-7-8/2018/task-14.svg","width":246,"height":142,"alt":"Развёртка коробки. К горизонтальной полосе из четырёх граней присоединены одна грань сверху и одна снизу. Отмечены длины 10 см, 7 см и 26 см."},"answer":2,"points":4,"review":[{"title":"Решение","text":"Пусть размеры прямоугольного основания a и b, а высота h. Горизонтальная полоса из четырёх боковых граней имеет длину 2a + 2b = 26 см, значит, a + b = 13 см."},{"title":"Решение","text":"Вертикальные размеры на рисунке равны h + a = 10 см и h + b = 7 см. Их сумма даёт 2h + 13 = 17 см, поэтому h = 2 см."},{"title":"Ответ","text":"Тогда a = 8 см и b = 5 см. Объём равен 8 × 5 × 2 = 80 см³."}]},{"number":15,"title":"Цифры простых чисел","question":"Используя каждую из цифр 1, 2, 3, 4, 5 ровно один раз, Алиса составляет список из нескольких простых чисел, меньших ста. Какое число обязательно будет в ее списке?","options":[{"text":"2"},{"text":"5"},{"text":"31"},{"text":"41"},{"text":"53"}],"condition":null,"answer":3,"points":4,"review":[{"title":"Решение","text":"Цифра 4 не может стоять в конце двузначного простого числа, а сама 4 составная. Из двузначных простых чисел с первой цифрой 4 подходят только 41 и 43."},{"title":"Решение","text":"Если взять 43, останутся 1, 2 и 5. Среди получаемых из них однозначных и двузначных чисел простые только 2 и 5, поэтому цифру 1 никак не использовать."},{"title":"Ответ","text":"Следовательно, в списке обязательно есть 41. После выбора 41 подходят, например, простые 2 и 53."}]},{"number":16,"title":"Средняя строка","question":"В прямоугольнике, состоящем из 40 клеток, больше одной строки. Вася закрасил все клетки средней строки. Сколько осталось незакрашенных клеток?","options":[{"text":"20"},{"text":"25"},{"text":"28"},{"text":"30"},{"text":"32"}],"condition":null,"answer":4,"points":4,"review":[{"title":"Решение","text":"Чтобы средняя строка была единственной, число строк должно быть нечётным. Оно также делит 40 и больше 1."},{"title":"Решение","text":"Единственный нечётный делитель 40, больший 1, — это 5. В каждой строке 40 ÷ 5 = 8 клеток."},{"title":"Ответ","text":"За вычетом закрашенной строки останется 40 − 8 = 32 клетки."}]},{"number":17,"title":"Школьники на лекции","question":"В классе 32 двухместные парты. За ними сидят 64 школьника и слушают лекцию. Оказалось, что 75 % мальчиков сидят рядом с девочками, а 45 % девочек сидят рядом с мальчиками. Сколько в аудитории девочек?","options":[{"text":"32"},{"text":"36"},{"text":"40"},{"text":"48"},{"text":"54"}],"condition":null,"answer":2,"points":4,"review":[{"title":"Решение","text":"Число мальчиков рядом с девочками равно числу девочек рядом с мальчиками, поскольку в каждой смешанной паре по одному ребёнку каждого пола."},{"title":"Решение","text":"Если мальчиков m, а девочек d, то 75m = 45d. После сокращения получаем 5m = 3d, то есть отношение m : d = 3 : 5."},{"title":"Ответ","text":"Из восьми равных частей по 64 ÷ 8 = 8 человек девочки составляют пять. Их 5 × 8 = 40."}]},{"number":18,"title":"Ломаная в прямоугольнике","question":"На рисунке изображен прямоугольник площади 24 с целыми сторонами. Какую наименьшую длину может иметь ломаная на рисунке?","options":[{"text":"12"},{"text":"16"},{"text":"17"},{"text":"18"},{"text":"22"}],"condition":{"src":"assets/grades-7-8/2018/task-18.svg","width":138,"height":96,"alt":"Прямоугольник целых ширины и высоты. Толстая ломаная идёт снизу вверх по левой стороне, вправо по части верха, вниз внутри, вправо по части низа и вверх по правой стороне."},"answer":2,"points":4,"review":[{"title":"Решение","text":"Два горизонтальных звена в сумме равны ширине w прямоугольника, а три вертикальных — утроенной высоте 3h. Длина ломаной равна w + 3h."},{"title":"Решение","text":"Проверяем делители 24 в качестве высоты. При h = 1, 2, 3, 4, 6 получаются длины 27, 18, 17, 18, 22 соответственно. При h ≥ 8 уже одна величина 3h больше 17."},{"title":"Ответ","text":"Наименьшая длина — 17 при высоте 3 и ширине 8."}]},{"number":19,"title":"Операция Васи","question":"Вася придумал новую операцию: a ⊗ b = ab + a − b. Если (x ⊗ 1) ⊗ 2 = 3, то x равен","options":[{"text":"1/2"},{"text":"2/3"},{"text":"1"},{"text":"6/5"},{"text":"4/3"}],"condition":null,"answer":4,"points":4,"review":[{"title":"Решение","text":"Сначала считаем x ⊗ 1 = x × 1 + x − 1 = 2x − 1."},{"title":"Решение","text":"Для любого a верно a ⊗ 2 = 3a − 2. Поэтому (x ⊗ 1) ⊗ 2 = 3(2x − 1) − 2 = 6x − 5."},{"title":"Ответ","text":"Решаем 6x − 5 = 3 и получаем x = 8/6 = 4/3."}]},{"number":20,"title":"Углы ломаной","question":"Валерий нарисовал внутри прямоугольника ломаную линию (см. рисунок). Градусные меры некоторых углов указаны. Чему равен угол x?","options":[{"text":"11°"},{"text":"12°"},{"text":"16°"},{"text":"17°"},{"text":"33°"}],"condition":{"src":"assets/grades-7-8/2018/task-20.svg","width":227,"height":170,"alt":"Ломаная из четырёх звеньев внутри прямоугольника. Сверху и снизу её звенья образуют с горизонтальными сторонами углы 10° и 26°. У правых вершин отмечены 14° и 33°, у левой — x."},"answer":0,"points":4,"review":[{"title":"Решение","text":"Верхняя и нижняя стороны прямоугольника параллельны. У правой вершины сверху крайнее звено составляет с горизонталью 10°. Следующее звено наклонено в другую сторону на 14° − 10° = 4°."},{"title":"Решение","text":"У нижней правой вершины крайнее звено образует с горизонталью 26°. Звено над ним наклонено в другую сторону на 33° − 26° = 7°."},{"title":"Ответ","text":"Угол x расположен между звеньями, наклонёнными вверх и вниз от горизонтали, поэтому x = 4° + 7° = 11°."}]},{"number":21,"title":"Соседи по периметру","question":"Риа хочет вписать числа в клетки на рисунке так, чтобы каждое число было равно сумме двух своих соседей. Два числа уже вписаны. Какое число будет в закрашенной клетке?","options":[{"text":"7"},{"text":"10"},{"text":"13"},{"text":"−13"},{"text":"−3"}],"condition":{"src":"assets/grades-7-8/2018/task-21.svg","width":152,"height":134,"alt":"Замкнутая цепочка клеток по краю прямоугольника размером шесть клеток на пять. Вверху слева 10, справа 3. В нижнем ряду вторая клетка слева закрашена."},"answer":0,"points":5,"review":[{"title":"Решение","text":"Обходим клетки по часовой стрелке, начиная с 10 в верхнем левом углу. Каждое следующее число равно текущему минус предыдущее. Если начать с 10 и b, получаем 10, b, b − 10, −10, −b, 10 − b, а потом те же числа снова."},{"title":"Решение","text":"Верхняя строка содержит ровно шесть клеток и заканчивается числом 3. Значит, 10 − b = 3, откуда b = 7."},{"title":"Ответ","text":"Закрашенная клетка имеет номер 14 в обходе, то есть занимает второе место в третьем повторе из шести. В ней стоит 7."}]},{"number":22,"title":"Квадрат произведения","question":"В наборе 2018 чисел: 2¹, 2², 2³, …, 2²⁰¹⁸. Сколькими способами из этого набора можно убрать одно число, чтобы произведение оставшихся чисел было квадратом некоторого натурального числа?","options":[{"text":"1007"},{"text":"1008"},{"text":"1009"},{"text":"2017"},{"text":"2018"}],"condition":null,"answer":2,"points":5,"review":[{"title":"Решение","text":"При умножении степеней двойки показатели складываются. Сумма показателей равна 2018 × 2019 ÷ 2 = 1009 × 2019, это нечётное число."},{"title":"Решение","text":"Степень двойки является квадратом тогда и только тогда, когда её показатель чётный. Значит, убрать надо любую степень с нечётным показателем."},{"title":"Ответ","text":"Из чисел от 1 до 2018 ровно 1009 нечётны, так что способов 1009."}]},{"number":23,"title":"Вася и Петя на дорожке","question":"На круговой дорожке из одной точки в противоположных направлениях стартовали одновременно Вася на велосипеде и Петя пешком. Скорость Васи в 4 раза больше скорости Пети. Проехав несколько кругов, Вася встретил Петю 20 раз. Сколько кругов он проехал?","options":[{"text":"15"},{"text":"16"},{"text":"17"},{"text":"20"},{"text":"21"}],"condition":null,"answer":1,"points":5,"review":[{"title":"Решение","text":"После старта очередная встреча происходит всякий раз, когда суммарно Вася и Петя проходят ещё один круг."},{"title":"Решение","text":"За один круг Васи Петя проходит 1/4 круга, поэтому суммарный путь равен 5/4 круга на каждый Васин круг."},{"title":"Ответ","text":"Двадцатая встреча случается после 20 ÷ (5/4) = 16 кругов Васи. Следующая была бы до окончания 17-го круга, так что подходит 16."}]},{"number":24,"title":"Таблица кратных сумм","question":"Сколькими способами в таблице 3 × 2 можно расставить числа 1, 2, 3, 4, 5, 6 так, чтобы в каждой строке и в каждом столбце сумма чисел делилась на 3?","options":[{"text":"36"},{"text":"40"},{"text":"42"},{"text":"48"},{"text":"60"}],"condition":null,"answer":3,"points":5,"review":[{"title":"Решение","text":"В каждой из трёх строк сумма двух остатков по модулю 3 равна 0 или 3. Числа 3 и 6 должны образовать одну строку, а числа 1 и 4 надо попарно соединить с 2 и 5. Это можно сделать двумя способами."},{"title":"Решение","text":"Готовые три пары можно расставить по строкам 3 × 2 × 1 = 6 способами. В строке с 3 и 6 есть два порядка."},{"title":"Ответ","text":"Для двух смешанных строк порядок первой пары выбираем двумя способами. Порядок второй пары уже определён: в каждом столбце должны встретиться один остаток 1 и один остаток 2. Всего 2 × 6 × 2 × 2 = 48 способов."}]},{"number":25,"title":"Треугольник в треугольнике","question":"Точки N, M и L лежат на сторонах правильного треугольника ABC, и при этом NM ⟂ BC, ML ⟂ AB и LN ⟂ AC. Площадь треугольника ABC равна 36. Чему равна площадь треугольника LNM?","options":[{"text":"9"},{"text":"12"},{"text":"15"},{"text":"16"},{"text":"18"}],"condition":{"src":"assets/grades-7-8/2018/task-25.svg","width":196,"height":182,"alt":"Равносторонний треугольник ABC с точками N на AC, M на BC и L на AB. Соединены N, M и L и отмечены прямые углы."},"answer":1,"points":5,"review":[{"title":"Решение","text":"На каждой стороне ABC лежит одна из точек N, M, L. Две точки на одной стороне дали бы отрезок, параллельный этой стороне, а ни одна сторона ABC не перпендикулярна другой. Отрезок NM должен иметь конец на BC: иначе его концы лежали бы на AB и AC по разные стороны от высоты из A, которой он параллелен. Аналогично ML имеет конец на AB, а LN — на AC. Получаются два зеркальных расположения. Рассмотрим то, что на рисунке."},{"title":"Решение","text":"Три стороны LNM перпендикулярны трём сторонам ABC. Углы между соседними сторонами поэтому равны 60° или 120°. Внутренние углы треугольника дают в сумме 180°, значит, все три равны 60°."},{"title":"Решение","text":"Пусть сторона LNM равна s. Треугольники ANL и CNM прямоугольные с углом 60° при A и C. По соотношениям сторон треугольника с углами 30°, 60° и 90° получаем AN = s/√3 и NC = 2s/√3."},{"title":"Ответ","text":"Следовательно, AC = √3s. Отношение площадей равно квадрату отношения сторон, поэтому площадь LNM равна 36 ÷ 3 = 12."}]},{"number":26,"title":"Очень счастливое число","question":"Шестизначное число назовем счастливым, если в нем сумма каких-то трех цифр равна сумме трех других. Счастливое число назовем очень счастливым, если следующее за ним число тоже счастливое. Найдите предпоследнюю цифру наименьшего очень счастливого числа.","options":[{"text":"1"},{"text":"2"},{"text":"3"},{"text":"4"},{"text":"5"}],"condition":null,"answer":3,"points":5,"review":[{"title":"Решение","text":"Сумма цифр счастливого числа чётна. При прибавлении 1 она меняется на 1 − 9t, где t — число девяток на конце. Поэтому у очень счастливого числа t нечётно. Для чисел до 100 449 это возможно только при одной девятке на конце."},{"title":"Решение","text":"Обозначим сумму первых четырёх цифр через S, а предпоследнюю цифру — через d. Чтобы девятку уравновесить остальными цифрами, необходимо S + d ≥ 9. У следующего числа нужно уравновесить d + 1, значит, S ≥ d + 1. Отсюда S ≥ 5."},{"title":"Ответ","text":"У чисел меньше 100 400 сумма первых четырёх цифр меньше 5. При первых цифрах 1004 она равна 5, а два неравенства требуют d = 4. Числа 100 449 и 100 450 подходят: в первом 9 = 1 + 4 + 4, во втором 5 = 1 + 4 + 0. Ответ — 4."}]},{"number":27,"title":"Рыцари по росту","question":"В комнате находятся 100 человек, каждый из которых либо рыцарь, который всегда говорит правду, либо лжец, который всегда лжет. Все они разного роста. Каждый из находящихся в комнате сказал одну из двух фраз: «Не менее пяти лжецов ниже меня»; «Не менее пяти лжецов выше меня». Какое наименьшее количество рыцарей может быть в этой комнате?","options":[{"text":"1"},{"text":"50"},{"text":"89"},{"text":"90"},{"text":"99"}],"condition":null,"answer":3,"points":5,"review":[{"title":"Решение","text":"Если бы лжецов было хотя бы 11, у шестого лжеца по росту было бы не меньше пяти лжецов и ниже, и выше. Обе фразы для него были бы истинны, что невозможно."},{"title":"Решение","text":"Десять лжецов могут быть десятью самыми низкими в комнате. Пятеро самых низких лжецов говорят, что ниже них не менее пяти лжецов, а остальные пятеро лжецов говорят это о более высоких. Обе группы говорят неправду."},{"title":"Ответ","text":"Все 90 более высоких рыцарей правдиво скажут, что ниже них не менее пяти лжецов. Поэтому минимум — 90."}]},{"number":28,"title":"Проценты общего делителя","question":"Наибольший общий делитель чисел a и b составляет 20 % от a. Сколько процентов он может составлять от b?","options":[{"text":"5"},{"text":"10"},{"text":"15"},{"text":"20"},{"text":"25"}],"condition":null,"answer":4,"points":5,"review":[{"title":"Решение","text":"Обозначим общий делитель через d. Тогда a = 5d, а b = kd для некоторого натурального k. Числа 5 и k взаимно просты, иначе d не был бы наибольшим общим делителем."},{"title":"Решение","text":"Доля d от b равна 1/k. Варианты 5 %, 10 % и 20 % требуют k = 20, 10 и 5, то есть кратных 5. Для 15 % число k не целое."},{"title":"Ответ","text":"При 25 % получается k = 4, взаимно простое с 5. Это возможно, например, при a = 5 и b = 4."}]},{"number":29,"title":"Две разметки отрезка","question":"Алиса отметила на отрезке 19 точек, разбивающих его на 20 равных частей. Антон отметил на этом же отрезке 12 точек, разбивающих его на 13 равных частей. В результате отрезок оказался разбит на много маленьких отрезков. Сколько разных длин у этих отрезков?","options":[{"text":"10"},{"text":"12"},{"text":"13"},{"text":"18"},{"text":"20"}],"condition":null,"answer":2,"points":5,"review":[{"title":"Решение","text":"Возьмём длину исходного отрезка за 260 единиц. У Алисы отрезки длиной 13, а отметки Антона стоят на расстояниях 20, 40, …, 240 от начала. В каждый отрезок Алисы попадает не больше одной отметки Антона."},{"title":"Решение","text":"При делении 20k на 13 числа k от 1 до 12 дают все остатки от 1 до 12, поскольку 20 и 13 взаимно просты. Это длины левых частей разрезанных отрезков Алисы. Правые части имеют длины 13 минус остаток и новых длин не добавляют."},{"title":"Ответ","text":"У восьми отрезков Алисы отметки внутри нет, поэтому остаётся и длина 13. Всего 13 разных длин."}]},{"number":30,"title":"Медиана BM","question":"В треугольнике ABC проведена медиана BM. Известно, что ∠AMB = 45°. На отрезке BM выбрана точка K такая, что AB = KC. Оказалось, что BK = 1. Найдите AC.","options":[{"text":"1"},{"text":"√2"},{"text":"1,5"},{"text":"√3"},{"text":"1,75"}],"condition":{"src":"assets/grades-7-8/2018/task-30.svg","width":282,"height":178,"alt":"Треугольник ABC с медианой BM. K лежит между B и M, отрезки AB и KC отмечены как равные, угол AMB равен 45°."},"answer":1,"points":5,"review":[{"title":"Решение","text":"Обозначим AM = MC через s, BM через b и KM через k. Тогда b − k = 1. Угол AMB равен 45°, а KMC — 135°."},{"title":"Решение","text":"По теореме косинусов AB² = b² + s² − √2bs, а KC² = k² + s² + √2ks. Из равенства AB = KC получаем (b − k)(b + k) = √2s(b + k)."},{"title":"Ответ","text":"Сокращаем на b + k и подставляем b − k = 1. Получаем s = 1/√2, поэтому AC = 2s = √2."}]}]}];
'use strict';

(() => {
  const archive = globalThis.KENGURU_ARCHIVE ??= {};
  const visual = globalThis.KenguruVisual;
  const cyrillicAnswers = 'АБВГД';

  function circleComparison(step, frame) {
    const outline = '#54877e';
    const fill = ['#347d75', '#43998c', '#60a99d', '#2e807c'];
    const ink = '#172e34';
    const radius = 43;
    const quarter = 'M0 0H43A43 43 0 0 0 0 -43Z';
    if (step === 1) {
      const opacity = .25 + .75 * visual.reveal(frame);
      return visual.svg(`<rect x="225" y="20" width="190" height="190" rx="3" fill="#f1f6ee" stroke="${outline}" stroke-width="2"/>
        <path d="M320 115H415A95 95 0 0 0 320 20Z" fill="${fill[0]}" opacity="${opacity}"/>
        <path d="M320 123V130M415 123V130M320 126H415" fill="none" stroke="${ink}" stroke-width="2"/>
        <text x="367.5" y="154" fill="${ink}" font-size="17" text-anchor="middle">радиус</text>`,
      'Радиус четверти круга равен половине стороны квадрата', '0 0 640 230', 'worked-scene');
    }
    if (step !== 2) return null;

    const far = radius;
    const offsets = [
      [[-far, far], [-far, -far], [far, -far], [far, far]],
      [[0, 0], [0, 0], [0, 0], [0, 0]],
      [[-far, 0], [-far, 0], [far, 0], [far, 0]],
      [[0, far], [-far, -far], [far, -far], [0, far]],
    ];
    const groups = offsets.map((pieces, index) => {
      const x = index % 2 === 0 ? 222 : 418;
      const y = index < 2 ? 95 : 254;
      const start = index * .38;
      const turn = index === 1 ? 0 : 180 * visual.reveal((frame - start) * 2.5);
      const remaining = 1 - visual.reveal((frame - start - 1.2) * 1.15);
      const paths = pieces.map(([dx, dy], piece) =>
        `<path d="${quarter}" fill="${fill[piece]}" stroke="#fffefa"
          stroke-width=".6" transform="translate(${x + dx * remaining} ${y + dy * remaining}) rotate(${90 * piece + turn})"/>`
      ).join('');
      return `<rect x="${x - radius}" y="${y - radius}" width="${radius * 2}" height="${radius * 2}"
        fill="#f1f6ee" stroke="${outline}" stroke-width="1.6"/>${paths}
        <text x="${x - 96}" y="${y + 6}" fill="${ink}" font-size="20" text-anchor="middle">${cyrillicAnswers[index]}</text>`;
    });
    return visual.svg(groups.join(''), 'Четыре четверти каждого рисунка складываются в целый круг',
      '102 0 432 348', 'worked-scene');
  }

  function shadeCells(step, frame) {
    if (step !== 2) return null;
    const alreadyShaded = [2, 4, 7, 9];
    const newlyShaded = [0, 1];
    const cells = Array.from({length: 12}, (_, index) => {
      const x = 90 + index % 4 * 42;
      const y = 20 + Math.floor(index / 4) * 42;
      const change = newlyShaded.indexOf(index);
      const opacity = alreadyShaded.includes(index) ? 1 : change < 0 ? 0 : visual.reveal(frame * 2 - change * .65);
      return `<rect x="${x}" y="${y}" width="42" height="42" fill="#fff"/>
        <rect x="${x}" y="${y}" width="42" height="42" fill="#202020" opacity="${opacity}"/>
        <rect x="${x}" y="${y}" width="42" height="42" fill="none" stroke="#202020" stroke-width="1.2"/>`;
    });
    return visual.svg(cells.join(''), 'В двух белых клетках верхней строки появляется чёрная заливка',
      '65 6 218 154', 'worked-scene');
  }

  const editions = [...(globalThis.KENGURU_GRADES_7_8 ?? []), ...(globalThis.KENGURU_JUNIOR_SENIOR ?? [])];
  for (const edition of editions) {
    const answerLetters = [...(edition.answerLetters ?? cyrillicAnswers)];
    const {id, year, label, grades, tasksUrl, answersUrl, solutionUrl, cards} = edition;
    const lessons = [];
    const scenes = [];

    for (const {number, title, question, questionNote, options, condition, answer, points, review, keyNote} of cards) {
      const hasReview = review.length > 0;
      const choiceImages = options.map(option => option.image);
      const choices = options.map(option => option.text ?? '');
      const answerLetter = answerLetters[answer];
      const steps = [['Условие', 'Условие задачи', '']];
      for (const [index, stage] of review.entries()) {
        const final = index === review.length - 1;
        steps.push([final ? 'Ответ' : 'Шаг ' + (index + 1), stage.title, stage.text]);
      }
      if (!hasReview) {
        steps.push(['Ответ', 'Проверка по ключу', keyNote ?? (answerLetter ? 'Правильный вариант — ' + answerLetter + '.' : 'Сверь решение с ответом в PDF.')]);
      }

      lessons.push({
        number, title, short: title, question, questionNote, points, answer, choices, choiceImages,
        choiceLayout: {condition, options}, conditionImage: condition?.src, conditionAlt: condition?.alt,
        hideIntroText: true, paperEdition: !hasReview, showCompletedStep: hasReview,
        officialValueKey: answer === null,
        steps,
      });

      const keyedAnswer = visual.answerScene({letter: answerLetter, value: choices[answer]});
      scenes.push((step, frame) => {
        if (!step) return '';
        if (!hasReview) return keyedAnswer;
        const stage = review[step - 1];
        const animation = id === '2026-7-8' && number === 1 ? circleComparison(step, frame)
          : id === '2017-2' && number === 6 ? shadeCells(step, frame) : null;
        return animation ?? (visual.workedScene(stage, frame)
          || (step === review.length ? keyedAnswer : ''));
      });
    }
    archive[id] = {id, year, label, grades, answerLetters, sources: {tasksUrl, answersUrl, solutionUrl}, lessons, scenes};
  }
})();

register((globalThis.KENGURU_ARCHIVE["2018-7-8"] ?? [].concat(globalThis.KENGURU_ARCHIVE[2018] ?? []).find(edition => edition.id === "2018-7-8")), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
